// Configure Timer0 for High-Frequency PWM on Pins 5 & 6
void setupHighFreqPWM() {
  // Set Fast PWM mode and 1/8 prescaler for 7.8 kHz PWM
  TCCR0A = _BV(COM0A1) | _BV(COM0B1) | _BV(WGM00) | _BV(WGM01);
  TCCR0B = _BV(CS01); // Prescaler 8

  pinMode(LEFT_PWM_PIN, OUTPUT);
  pinMode(RIGHT_PWM_PIN, OUTPUT);
}

void loop() {
  int leftSense = analogRead(IR_LEFT_PIN);
  int rightSense = analogRead(IR_RIGHT_PIN);
  int error = leftSense - rightSense;

  int leftSpeed = constrain(BASE_SPEED + (error * KP), 0, 255);
  int rightSpeed = constrain(BASE_SPEED - (error * KP), 0, 255);

  analogWrite(LEFT_PWM_PIN, leftSpeed);
  analogWrite(RIGHT_PWM_PIN, rightSpeed);
}
